1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    :root {
9	      --circle-hue: #8ec5ff;
10	      --circle-core: #4a7dd9;
11	      --circle-shadow: #1f3a75;
12	      --cycle: 2.5s;
13	    }
14	    * {
15	      margin: 0;
16	      padding: 0;
17	      box-sizing: border-box;
18	    }
19	    body {
20	      width: 100vw;
21	      height: 100vh;
22	      display: flex;
23	      flex-direction: column;
24	      justify-content: center;
25	      align-items: center;
26	      gap: 24px;
27	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
28	      overflow: hidden;
29	    }
30	    svg {
31	      width: min(400px, 80vmin);
32	      height: min(400px, 80vmin);
33	      overflow: visible;
34	      cursor: pointer;
35	      transition: filter 0.3s ease;
36	    }
37	    svg:hover {
38	      filter: brightness(1.08);
39	    }
40	    svg:focus-visible {
41	      outline: 2px solid var(--circle-hue);
42	      outline-offset: 8px;
43	      border-radius: 50%;
44	    }
45	    .ambient {
46	      fill: var(--circle-hue);
47	      opacity: 0.12;
48	      filter: blur(30px);
49	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
50	      transform-origin: 200px 200px;
51	      will-change: transform, opacity;
52	    }
53	    .core {
54	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      filter: url(#glow);
57	      will-change: transform, opacity;
58	    }
59	    .highlight {
60	      fill: url(#highlightGradient);
61	      transform-origin: 200px 200px;
62	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
63	      pointer-events: none;
64	      will-change: transform, opacity;
65	    }
66	    .ring {
67	      fill: none;
68	      stroke: var(--circle-hue);
69	      stroke-width: 2.5;
70	      transform-origin: 200px 200px;
71	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
72	      will-change: transform, opacity, stroke-width;
73	    }
74	    .ring--delay-1 {
75	      animation-delay: calc(var(--cycle) / 3);
76	    }
77	    .ring--delay-2 {
78	      animation-delay: calc(var(--cycle) / 3 * 2);
79	    }
80	    @keyframes pulse {
81	      0%, 100% {
82	        transform: scale(1);
83	        opacity: 0.9;
84	      }
85	      50% {
86	        transform: scale(1.05);
87	        opacity: 1;
88	      }
89	    }
90	    @keyframes breathe {
91	      0%, 100% {
92	        transform: scale(0.95);
93	        opacity: 0.1;
94	      }
95	      50% {
96	        transform: scale(1.1);
97	        opacity: 0.18;
98	      }
99	    }
100	    @keyframes ripple {
101	      0% {
102	        transform: scale(1);
103	        opacity: 0.6;
104	        stroke-width: 2.5;
105	      }
106	      100% {
107	        transform: scale(1.35);
108	        opacity: 0;
109	        stroke-width: 0.5;
110	      }
111	    }
112	    body.paused .core,
113	    body.paused .ring,
114	    body.paused .ambient,
115	    body.paused .highlight {
116	      animation-play-state: paused;
117	    }
118	    @media (prefers-reduced-motion: reduce) {
119	      .core, .ring, .ambient, .highlight {
120	        animation-play-state: paused;
121	      }
122	    }
123	    .speed-label {
124	      color: var(--circle-hue);
125	      font-family: system-ui, sans-serif;
126	      font-size: 0.85rem;
127	      letter-spacing: 0.05em;
128	      opacity: 0.7;
129	      user-select: none;
130	      text-align: center;
131	    }
132	    .hint {
133	      display: block;
134	      margin-top: 4px;
135	      font-size: 0.7rem;
136	      opacity: 0.75;
137	    }
138	  </style>
139	</head>
140	<body>
141	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed. Press space to pause." aria-describedby="speedText" aria-pressed="false">
142	    <defs>
143	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
144	        <stop offset="0%" stop-color="#8ec5ff"/>
145	        <stop offset="55%" stop-color="#4a7dd9"/>
146	        <stop offset="100%" stop-color="#1f3a75"/>
147	      </radialGradient>
148	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
149	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
150	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
151	      </radialGradient>
152	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
153	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
154	        <feColorMatrix in="blur" type="matrix"
155	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
156	        <feMerge>
157	          <feMergeNode in="tintedBlur"/>
158	          <feMergeNode in="SourceGraphic"/>
159	        </feMerge>
160	      </filter>
161	    </defs>
162	    <circle class="ambient" cx="200" cy="200" r="160"/>
163	    <circle class="ring" cx="200" cy="200" r="140"/>
164	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
165	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
166	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
167	    <circle class="highlight" cx="200" cy="200" r="140"/>
168	  </svg>
169	  <p class="speed-label" id="speedLabel" aria-live="polite">
170	    <span id="speedText">Normal speed</span>
171	    <span class="hint">Click to change speed · Space to pause</span>
172	  </p>
173	  <script>
174	    const svg = document.getElementById('ae683f770');
175	    const speedText = document.getElementById('speedText');
176	    const speeds = [
177	      { value: '2.5s', name: 'Normal speed' },
178	      { value: '1.2s', name: 'Fast speed' },
179	      { value: '4.5s', name: 'Slow speed' },
180	    ];
181	    let speedIndex = 0;
182	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
183	    let manuallyPaused = reducedMotionQuery.matches;
184	
185	    function updateLabels() {
186	      const { name } = speeds[speedIndex];
187	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
188	    }
189	
190	    function cycleSpeed() {
191	      speedIndex = (speedIndex + 1) % speeds.length;
192	      const { value } = speeds[speedIndex];
193	      svg.style.setProperty('--cycle', value);
194	      // Restart animations from the beginning so the new speed feels immediate
195	      // instead of jumping mid-cycle.
196	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
197	        el.style.animation = 'none';
198	        void el.offsetWidth;
199	        el.style.animation = '';
200	      });
201	      updateLabels();
202	    }
203	
204	    function togglePause() {
205	      manuallyPaused = !manuallyPaused;
206	      document.body.classList.toggle('paused', manuallyPaused);
207	      svg.setAttribute('aria-pressed', String(manuallyPaused));
208	      updateLabels();
209	    }
210	
211	    svg.addEventListener('click', cycleSpeed);
212	    svg.addEventListener('keydown', (e) => {
213	      if (e.key === 'Enter') {
214	        e.preventDefault();
215	        cycleSpeed();
216	      } else if (e.key === ' ') {
217	        e.preventDefault();
218	        togglePause();
219	      }
220	    });
221	
222	    document.addEventListener('visibilitychange', () => {
223	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
224	    });
225	
226	    reducedMotionQuery.addEventListener('change', (e) => {
227	      manuallyPaused = e.matches;
228	      document.body.classList.toggle('paused', manuallyPaused);
229	      svg.setAttribute('aria-pressed', String(manuallyPaused));
230	      updateLabels();
231	    });
232	
233	    document.body.classList.toggle('paused', manuallyPaused);
234	    svg.setAttribute('aria-pressed', String(manuallyPaused));
235	    updateLabels();
236	  </script>
237	</body>
238	</html>
